{"query": "
SELECT table_schema, table_name
FROM information_schema.tables
WHERE table_schema NOT IN ('pg_catalog', 'information_schema', 'extensions', 'auth', 'storage', 'realtime', 'pgsodium', 'vault', 'graphql_public', 'graphql', 'pgbouncer', 'cron')
ORDER BY table_schema, table_name;
"}

{"query": "
SELECT table_schema, table_name
FROM information_schema.tables
WHERE table_schema = 'employees'
ORDER BY table_name;
"}

{"query": "
-- ============================================================
-- STEP 1: Create employee_performance_analysis table
-- ============================================================
DROP TABLE IF EXISTS employees.employee_performance_analysis;

CREATE TABLE employees.employee_performance_analysis (
    employee_id        BIGINT       NOT NULL,
    performance_category VARCHAR(20) NOT NULL,
    salary_growth_rate DECIMAL(10,4) NOT NULL,
    days_of_service    INTEGER      NOT NULL,
    promotion_count    INTEGER      NOT NULL
);
"}

{"query": "
-- ============================================================
-- STEP 3: Create department_salary_analysis table
-- ============================================================
DROP TABLE IF EXISTS employees.department_salary_analysis;

CREATE TABLE employees.department_salary_analysis (
    department_name    VARCHAR(100) NOT NULL,
    avg_current_salary DECIMAL(12,4) NOT NULL,
    employee_count     INTEGER      NOT NULL,
    salary_range_spread INTEGER     NOT NULL
);
"}
